const target = { 
  secret: 'shhh',
  public: 'hello'
};

const handler = {
  // 1. 읽기(Get) 동작을 가로채는 Trap
  get(obj, prop) {
    if (prop === 'secret') {
      return 'Access Denied!';
    }
    // 2. 나머지는 원본 객체에게 전달 (Forwarding)
    return Reflect.get(obj, prop);
  }
};

// 원본(Target)을 감싸는 Proxy 생성
const proxy = new Proxy(target, handler);

console.log(proxy.public); // hello
console.log(proxy.secret); // Access Denied!
